1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>VenueBook · 场地预约与活动报名</title>
6	<style>
7	  :root { color-scheme: light; }
8	  * { box-sizing: border-box; }
9	  body { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; max-width: 56rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
10	  h1 { margin-bottom: .2rem; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #d9e2ec; padding-bottom: .3rem; }
12	  a { color: #175b9c; }
13	  .muted { color: #616e7c; }
14	  form { background: #f8fafc; border: 1px solid #d9e2ec; border-radius: .6rem; padding: 1.2rem 1.4rem; }
15	  .field { margin-bottom: 1rem; }
16	  label { display: block; font-weight: 600; margin-bottom: .25rem; }
17	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #b7c2cd; border-radius: .35rem; background: #fff; }
18	  input[type=text], input[type=number] { width: 14rem; max-width: 100%; }
19	  .hint { font-weight: 400; color: #616e7c; font-size: .9rem; }
20	  fieldset { border: 1px dashed #b7c2cd; border-radius: .5rem; margin: 0 0 1rem; padding: .8rem 1rem 1rem; }
21	  legend { font-weight: 600; padding: 0 .4rem; }
22	  .hour-row { display: flex; flex-wrap: wrap; gap: .5rem; align-items: center; margin-bottom: .5rem; }
23	  .hour-row select, .hour-row input { width: auto; }
24	  button { font: inherit; padding: .45rem 1.1rem; border-radius: .4rem; border: 1px solid #175b9c; background: #175b9c; color: #fff; cursor: pointer; }
25	  button.secondary { background: #fff; color: #175b9c; }
26	  button.danger { background: #fff; color: #b42318; border-color: #b42318; padding: .3rem .7rem; }
27	  #form-error { margin-top: .9rem; color: #b42318; font-weight: 600; white-space: pre-wrap; display: none; }
28	  .venue-card { border: 1px solid #d9e2ec; border-radius: .6rem; padding: 1rem 1.3rem; margin-bottom: 1rem; background: #fff; }
29	  .venue-card h3 { margin: 0 0 .3rem; }
30	  .venue-meta { color: #52606d; margin: .15rem 0; }
31	  .hours { margin: .5rem 0 0; padding: 0; list-style: none; }
32	  .hours li { display: inline-block; background: #eef4fa; border-radius: 999px; padding: .15rem .8rem; margin: 0 .4rem .4rem 0; font-size: .92rem; }
33	  .empty { color: #616e7c; background: #f8fafc; border: 1px dashed #b7c2cd; border-radius: .6rem; padding: 1.2rem; text-align: center; }
34	  .next-day { color: #b42318; font-size: .85em; }
35	</style>
36	<main>
37	  <h1>VenueBook</h1>
38	  <p class="muted">场地预约与活动报名。<a href="/api/venues">场地列表接口</a> · <a href="/health">服务状态</a></p>
39	
40	  <h2>新增场地</h2>
41	  <form id="venue-form" novalidate>
42	    <div class="field">
43	      <label for="name">名称</label>
44	      <input id="name" name="name" type="text" autocomplete="off" required>
45	    </div>
46	    <div class="field">
47	      <label for="capacity">容量（人）</label>
48	      <input id="capacity" name="capacity" type="number" min="1" step="1" required>
49	    </div>
50	    <div class="field">
51	      <label for="timezone">所在时区</label>
52	      <input id="timezone" name="timezone" type="text" list="tz-list" placeholder="Asia/Shanghai" autocomplete="off" required>
53	      <datalist id="tz-list">
54	        <option value="Asia/Shanghai">
55	        <option value="Asia/Tokyo">
56	        <option value="Asia/Singapore">
57	        <option value="Asia/Hong_Kong">
58	        <option value="Asia/Taipei">
59	        <option value="Asia/Seoul">
60	        <option value="Asia/Kolkata">
61	        <option value="Asia/Dubai">
62	        <option value="Asia/Bangkok">
63	        <option value="Europe/London">
64	        <option value="Europe/Paris">
65	        <option value="Europe/Berlin">
66	        <option value="Australia/Sydney">
67	        <option value="America/New_York">
68	        <option value="America/Chicago">
69	        <option value="America/Los_Angeles">
70	        <option value="UTC">
71	      </datalist>
72	      <div class="hint">有效的 IANA 时区名称，例如 Asia/Shanghai；开放时间按此时区解释。</div>
73	    </div>
74	    <fieldset>
75	      <legend>每周开放时间（可为空）</legend>
76	      <div id="hours-rows"></div>
77	      <button type="button" id="add-hour" class="secondary">添加开放时段</button>
78	    </fieldset>
79	    <button type="submit">保存</button>
80	    <div id="form-error" role="alert"></div>
81	  </form>
82	
83	  <h2>场地列表</h2>
84	  <div id="venue-list">
85	    <div class="empty">正在加载…</div>
86	  </div>
87	</main>
88	
89	<script>
90	(function () {
91	  var WEEKDAYS = { 1: "周一", 2: "周二", 3: "周三", 4: "周四", 5: "周五", 6: "周六", 7: "周日" };
92	
93	  var form = document.getElementById("venue-form");
94	  var hoursRows = document.getElementById("hours-rows");
95	  var errorBox = document.getElementById("form-error");
96	  var listBox = document.getElementById("venue-list");
97	
98	  function showError(message) {
99	    errorBox.textContent = message;
100	    errorBox.style.display = "block";
101	  }
102	  function clearError() {
103	    errorBox.textContent = "";
104	    errorBox.style.display = "none";
105	  }
106	
107	  function addHourRow() {
108	    var row = document.createElement("div");
109	    row.className = "hour-row";
110	    var weekday = document.createElement("select");
111	    weekday.className = "hour-weekday";
112	    Object.keys(WEEKDAYS).forEach(function (d) {
113	      var opt = document.createElement("option");
114	      opt.value = d;
115	      opt.textContent = WEEKDAYS[d];
116	      weekday.appendChild(opt);
117	    });
118	    var start = document.createElement("input");
119	    start.type = "time"; start.className = "hour-start"; start.required = true;
120	    var dash = document.createElement("span");
121	    dash.textContent = "至";
122	    var end = document.createElement("input");
123	    end.type = "time"; end.className = "hour-end"; end.required = true;
124	    var remove = document.createElement("button");
125	    remove.type = "button";
126	    remove.className = "danger";
127	    remove.textContent = "删除";
128	    remove.addEventListener("click", function () { row.remove(); });
129	    row.appendChild(weekday);
130	    row.appendChild(start);
131	    row.appendChild(dash);
132	    row.appendChild(end);
133	    row.appendChild(remove);
134	    hoursRows.appendChild(row);
135	  }
136	  document.getElementById("add-hour").addEventListener("click", addHourRow);
137	
138	  function collectHours() {
139	    var rows = hoursRows.querySelectorAll(".hour-row");
140	    var hours = [];
141	    for (var i = 0; i < rows.length; i++) {
142	      var weekday = parseInt(rows[i].querySelector(".hour-weekday").value, 10);
143	      var start = rows[i].querySelector(".hour-start").value;
144	      var end = rows[i].querySelector(".hour-end").value;
145	      if (!start || !end) {
146	        return { error: "第 " + (i + 1) + " 个开放时段未填写完整，请补全或删除该时段。" };
147	      }
148	      hours.push({ weekday: weekday, start: start, end: end });
149	    }
150	    return { hours: hours };
151	  }
152	
153	  function toMinutes(hhmm) {
154	    var parts = hhmm.split(":");
155	    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
156	  }
157	
158	  function escapeHTML(value) {
159	    return String(value).replace(/[&<>"']/g, function (c) {
160	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
161	    });
162	  }
163	
164	  // canonicalDigits 按十进制原文校验容量输入：只接受由数字组成的正整数，
165	  // 返回去掉前导零后的数字原文；为空、为零或包含负号、小数点等内容时返回
166	  // null。全程不经过 Number/parseInt，否则 9007199254740993 这样超过
167	  // Number.MAX_SAFE_INTEGER 的值会被悄悄舍入成相邻整数。
168	  function canonicalDigits(raw) {
169	    if (!/^\d+$/.test(raw)) return null;
170	    var digits = raw.replace(/^0+/, "");
171	    if (digits === "") return null; // 全是 0：容量为零，不接受
172	    return digits;
173	  }
174	
175	  // buildVenueRequestBody 直接拼接 JSON 文本，让容量以输入的十进制数字原文
176	  // 发送：不能用 JSON.stringify({capacity: 数字})，大整数在转成 Number 时
177	  // 已经被舍入，stringify 只会写回错误的值。名称、时区是字符串，交给
178	  // JSON.stringify 转义；传输报文中 capacity 仍是 JSON 数字。
179	  function buildVenueRequestBody(name, capacityDigits, timezone, hours) {
180	    return "{" +
181	      '"name":' + JSON.stringify(name) +
182	      ',"capacity":' + capacityDigits +
183	      ',"timezone":' + JSON.stringify(timezone) +
184	      ',"weeklyHours":' + JSON.stringify(hours) +
185	      "}";
186	  }
187	
188	  // parseVenuesJSON 解析场地列表，但保留 capacity 数字的十进制原文：
189	  // JSON.parse 会把数字存成 float64，超过 2^53 的容量会被舍入成相邻整数。
190	  // 这里逐字符扫描 JSON（正确处理字符串内的转义引号），仅当 "capacity"
191	  // 作为对象键出现时，把其后数字的原文包成字符串，页面拿到的就是服务端
192	  // 逐位发出的完整十进制数字（服务端只输出普通整数，不会出现科学计数法）。
193	  // 名称等其它字段一律原样复制，绝不改写；线上传输的 JSON 中 capacity
194	  // 仍是数字，接口格式不变。
195	  function parseVenuesJSON(text) {
196	    var out = "", i = 0, n = text.length;
197	    while (i < n) {
198	      if (text[i] !== '"') {
199	        out += text[i];
200	        i++;
201	        continue;
202	      }
203	      // 读取完整字符串，跳过转义字符，使名称中出现的 \"capacity\":1
204	      // 之类文本不会被误认为对象键。
205	      var tokenStart = i, j = i + 1;
206	      while (j < n) {
207	        if (text[j] === "\\") { j += 2; continue; }
208	        if (text[j] === '"') { j++; break; }
209	        j++;
210	      }
211	      var token = text.slice(tokenStart, j);
212	      // 对象键后面（允许空白）必然是 ':'；字符串值后面只能是 ',' 或 '}'。
213	      var k = j;
214	      while (k < n && /\s/.test(text[k])) k++;
215	      if (text[k] !== ":" || JSON.parse(token) !== "capacity") {
216	        out += token;
217	        i = j;
218	        continue;
219	      }
220	      // 复制到 ':' 之后（含中间空白），再把数字原文引用为字符串。
221	      out += token + text.slice(j, k + 1);
222	      var p = k + 1;
223	      while (p < n && /\s/.test(text[p])) { out += text[p]; p++; }
224	      var numStart = p;
225	      while (p < n && /[-+0-9eE.]/.test(text[p])) p++;
226	      out += JSON.stringify(text.slice(numStart, p));
227	      i = p;
228	    }
229	    return JSON.parse(out);
230	  }
231	
232	  function renderVenues(venues) {
233	    if (!venues.length) {
234	      listBox.innerHTML = '<div class="empty">还没有场地记录。</div>';
235	      return;
236	    }
237	    var sortedHours = function (hours) {
238	      return hours.slice().sort(function (a, b) {
239	        if (a.weekday !== b.weekday) return a.weekday - b.weekday;
240	        return toMinutes(a.start) - toMinutes(b.start);
241	      });
242	    };
243	    listBox.innerHTML = venues.map(function (venue) {
244	      var hoursHTML;
245	      if (!venue.weeklyHours || !venue.weeklyHours.length) {
246	        hoursHTML = '<p class="venue-meta">开放时段：暂未开放</p>';
247	      } else {
248	        var items = sortedHours(venue.weeklyHours).map(function (h) {
249	          var overnight = toMinutes(h.end) < toMinutes(h.start);
250	          var endLabel = overnight ? '<span class="next-day">次日 ' + escapeHTML(h.end) + "</span>" : escapeHTML(h.end);
251	          return "<li>" + WEEKDAYS[h.weekday] + " " + escapeHTML(h.start) + " – " + endLabel + "</li>";
252	        }).join("");
253	        hoursHTML = '<ul class="hours">' + items + "</ul>";
254	      }
255	      return '<article class="venue-card">' +
256	        "<h3>" + escapeHTML(venue.name) + "</h3>" +
257	        '<p class="venue-meta">容量：' + escapeHTML(venue.capacity) + " 人</p>" +
258	        '<p class="venue-meta">时区：' + escapeHTML(venue.timezone) + "</p>" +
259	        hoursHTML +
260	        "</article>";
261	    }).join("");
262	  }
263	
264	  function loadVenues() {
265	    return fetch("/api/venues", { headers: { Accept: "application/json" } })
266	      .then(function (res) {
267	        if (!res.ok) throw new Error("读取场地列表失败（HTTP " + res.status + "）");
268	        return res.text();
269	      })
270	      .then(function (text) {
271	        var data;
272	        try {
273	          data = parseVenuesJSON(text);
274	        } catch (e) {
275	          throw new Error("读取场地列表失败：响应不是有效的 JSON");
276	        }
277	        renderVenues(data.venues || []);
278	      })
279	      .catch(function (err) {
280	        listBox.innerHTML = '<div class="empty">' + escapeHTML(err.message) + "</div>";
281	      });
282	  }
283	
284	  form.addEventListener("submit", function (event) {
285	    event.preventDefault();
286	    clearError();
287	
288	    var name = document.getElementById("name").value.trim();
289	    var capacityDigits = canonicalDigits(document.getElementById("capacity").value);
290	    var timezone = document.getElementById("timezone").value.trim();
291	
292	    if (!name) { showError("保存失败：名称不能为空。"); return; }
293	    if (capacityDigits === null) { showError("保存失败：容量必须是正整数。"); return; }
294	    if (!timezone) { showError("保存失败：请填写所在时区。"); return; }
295	
296	    var collected = collectHours();
297	    if (collected.error) { showError("保存失败：" + collected.error); return; }
298	
299	    // 失败时不重置表单，保留全部填写内容。
300	    fetch("/api/venues", {
301	      method: "POST",
302	      headers: { "Content-Type": "application/json", Accept: "application/json" },
303	      // 容量按输入的十进制原文作为 JSON 数字发送，不经过 Number/parseInt：
304	      // 是否超出服务端范围由服务端按这个准确整数判断，绝不先舍入再提交。
305	      body: buildVenueRequestBody(name, capacityDigits, timezone, collected.hours)
306	    }).then(function (res) {
307	      return res.json().catch(function () { return {}; }).then(function (body) {
308	        return { ok: res.ok, status: res.status, body: body };
309	      });
310	    }).then(function (result) {
311	      if (!result.ok) {
312	        var reason = result.body && result.body.error ? result.body.error : "HTTP " + result.status;
313	        showError("保存失败：" + reason);
314	        return;
315	      }
316	      form.reset();
317	      hoursRows.innerHTML = "";
318	      clearError();
319	      return loadVenues();
320	    }).catch(function (err) {
321	      showError("保存失败：无法连接服务（" + err.message + "），请稍后重试。");
322	    });
323	  });
324	
325	  loadVenues();
326	})();
327	</script>
328	</html>
