363	async function poll(fn, { timeout = 6000, interval = 80, label = "" } = {}) {
364	  const deadline = Date.now() + timeout;
365	  let lastErr;
366	  while (Date.now() < deadline) {
367	    try {
368	      const v = await fn();
369	      if (v) return v;
370	    } catch (e) { lastErr = e; }
371	    await sleep(interval);
372	  }
373	  throw new Error(`等待页面状态超时${label ? "（" + label + "）" : ""}${lastErr ? ": " + lastErr.message : ""}`);
374	}
