102	func newHandler(records *store) http.Handler {
103		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
104			route := r.URL.Path
105			allow, known := allowedMethods[route]
106			if !known {
107				errorJSON(w, http.StatusNotFound, "not found")
108				return
109			}
110			if route == "/api/venues" {
111				switch r.Method {
112				case http.MethodGet:
113					handleListVenues(w, r, records)
114					return
115				case http.MethodPost:
116					handleCreateVenue(w, r, records)
117					return
118				default:
119					w.Header().Set("Allow", allow)
120					errorJSON(w, http.StatusMethodNotAllowed, "method not allowed")
121					return
122				}
123			}
124			if r.Method != http.MethodGet {
125				w.Header().Set("Allow", allow)
126				errorJSON(w, http.StatusMethodNotAllowed, "method not allowed")
127				return
128			}
129			if route == "/" {
130				w.Header().Set("Content-Type", "text/html; charset=utf-8")
131				_, _ = fmt.Fprint(w, page)
132				return
133			}
