139	func handleListVenues(w http.ResponseWriter, _ *http.Request, records *store) {
140		venues, err := records.list()
141		if err != nil {
142			// 读不到或数据损坏时返回 500，绝不能回写空列表覆盖已有记录。
143			errorJSON(w, http.StatusInternalServerError, "unable to read venues")
144			return
145		}
146		writeJSON(w, http.StatusOK, map[string]any{resourceName: venues})
147	}
