149	func handleCreateVenue(w http.ResponseWriter, r *http.Request, records *store) {
150		// 限制请求体大小，避免异常大请求占用内存。
151		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
152		var payload map[string]any
153		decoder := json.NewDecoder(r.Body)
154		// 容量等整数字段必须按 JSON 数字的原文逐位判断：UseNumber 让数字以
155		// json.Number（原始文本）保留，避免 float64 舍入把 120.00000000000000001
156		// 变成 120、把 9007199254740993 变成相邻整数。
157		decoder.UseNumber()
158		if err := decoder.Decode(&payload); err != nil {
159			errorJSON(w, http.StatusBadRequest, "请求体不是有效的 JSON 对象："+err.Error())
160			return
161		}
162		// 拒绝同一请求体中的多余 JSON 值（如 {} {}）。
163		var extra json.RawMessage
164		if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
165			errorJSON(w, http.StatusBadRequest, "请求体中存在多余的 JSON 内容")
166			return
167		}
168		if payload == nil {
169			errorJSON(w, http.StatusBadRequest, "请求体必须是 JSON 对象")
170			return
171		}
172	
173		venue, err := records.create(payload)
174		if err != nil {
175			var bad *apiError
176			if errors.As(err, &bad) {
177				errorJSON(w, http.StatusBadRequest, bad.Error())
178				return
179			}
180			// 读不到已有数据、数据损坏或保存失败：不增加任何记录。
181			errorJSON(w, http.StatusInternalServerError, "unable to save venue")
182			return
183		}
184		writeJSON(w, http.StatusCreated, map[string]any{"venue": venue})
185	}
