  form.addEventListener("submit", function (event) {
    event.preventDefault();
    clearError();

    var name = document.getElementById("name").value.trim();
    var capacityDigits = canonicalDigits(document.getElementById("capacity").value);
    var timezone = document.getElementById("timezone").value.trim();

    if (!name) { showError("保存失败：名称不能为空。"); return; }
    if (capacityDigits === null) { showError("保存失败：容量必须是正整数。"); return; }
    if (!timezone) { showError("保存失败：请填写所在时区。"); return; }

    var collected = collectHours();
    if (collected.error) { showError("保存失败：" + collected.error); return; }

    // 记录发起本次保存时的改动计数：响应返回后只有计数未变（等待期间没有
    // 任何编辑/行变动）才允许清空表单。本次提交的仍是点击保存那一刻收集的
    // name/capacityDigits/timezone/collected，后续编辑不会改动这份报文。
    var submittedEditCount = formEditCount;

    // 失败时不重置表单，保留全部填写内容。
    fetch("/api/venues", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      // 容量按输入的十进制原文作为 JSON 数字发送，不经过 Number/parseInt：
      // 是否超出服务端范围由服务端按这个准确整数判断，绝不先舍入再提交。
      body: buildVenueRequestBody(name, capacityDigits, timezone, collected.hours)
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (body) {
        return { ok: res.ok, status: res.status, body: body };
      });
    }).then(function (result) {
      if (!result.ok) {
        var reason = result.body && result.body.error ? result.body.error : "HTTP " + result.status;
        // 服务端拒绝：展示本次保存的失败原因，表单保留用户当前填写的内容
        // （可能已在等待期间被继续修改），绝不恢复成提交时的旧值。
        showError("保存失败：" + reason);
        return;
      }
      // 成功只代表“点击保存那一刻的内容”已入库，列表始终来自服务端返回的
      // 已保存数据，不会混入等待期间的改动。
      var reload = loadVenues();
      if (formEditCount !== submittedEditCount) {
        // 等待期间名称、容量、时区或开放时段被增删改：完整保留当前整份
        // 表单（含空字段、非法容量或未填完的时段行与行的先后顺序），让
        // 用户继续填写；这些未提交的内容既不阻止成功记录展示，也不能被
        // 成功回调清掉。
        return reload;
      }
      // 提交后没有再改任何内容：保持原有成功行为，清空字段、移除时段行、
      // 消除错误提示。
      form.reset();
      hoursRows.innerHTML = "";
      clearError();
      return reload;
    }).catch(function (err) {
      showError("保存失败：无法连接服务（" + err.message + "），请稍后重试。");
    });
  });

  loadVenues();
})();
</script>
</html>

