// 临时验证脚本：保存响应延迟返回期间继续编辑的竞态场景。
import { spawn } from "node:child_process";
import fs from "node:fs";
import http from "node:http";
import net from "node:net";
import os from "node:os";
import path from "node:path";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const INDEX = fs.readFileSync(path.join(process.env.PWD, "index.html"), "utf8");

// 可控延迟/拒绝/断连的测试服务端。
const venues = [];
let delayMs = 1200;
const server = http.createServer((req, res) => {
  if (req.method === "GET" && req.url === "/") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(INDEX);
    return;
  }
  if (req.method === "GET" && req.url.startsWith("/api/venues")) {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ venues }));
    return;
  }
  if (req.method === "POST" && req.url.startsWith("/api/venues")) {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      setTimeout(() => {
        if (body.includes('"drop":true')) { req.socket.destroy(); return; }
        let payload;
        try { payload = JSON.parse(body); } catch { payload = {}; }
        if (String(payload.capacity) === "13") {
          res.writeHead(400, { "Content-Type": "application/json" });
          res.end(JSON.stringify({ error: "容量 13 不吉利，被服务端拒绝" }));
          return;
        }
        const venue = Object.assign({ id: "v" + (venues.length + 1) }, payload);
        venues.push(venue);
        res.writeHead(201, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ venue }));
      }, delayMs);
    });
    return;
  }
  res.writeHead(404); res.end();
});
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const baseURL = `http://127.0.0.1:${server.address().port}`;

// ---- chrome + CDP（与正式脚本同样的裸 CDP 方式）----
function freePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, "127.0.0.1", () => { const p = srv.address().port; srv.close(() => resolve(p)); });
    srv.on("error", reject);
  });
}
const port = await freePort();
const profile = fs.mkdtempSync(path.join(os.tmpdir(), "race-chrome-"));
const chrome = spawn("/usr/bin/google-chrome", [
  "--headless=new", "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
  `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`, "about:blank",
], { stdio: ["ignore", "ignore", "pipe"], detached: true });
for (let i = 0; i < 60; i++) {
  await sleep(100);
  try { if ((await fetch(`http://127.0.0.1:${port}/json/version`)).ok) break; } catch {}
}

class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); }
  async connect() {
    await new Promise((res, rej) => {
      this.ws.addEventListener("open", res, { once: true });
      this.ws.addEventListener("error", rej, { once: true });
    });
    this.ws.addEventListener("message", (ev) => {
      const m = JSON.parse(ev.data);
      if (m.id && this.pending.has(m.id)) {
        const { resolve, reject } = this.pending.get(m.id);
        this.pending.delete(m.id);
        m.error ? reject(new Error(m.error.message)) : resolve(m.result);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async eval(e) {
    const r = await this.send("Runtime.evaluate", { expression: e, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.text);
    return r.result ? r.result.value : undefined;
  }
}
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const cdp = new CDP(new WebSocket(list.find((t) => t.type === "page").webSocketDebuggerUrl));
await cdp.connect();
await cdp.send("Page.enable"); await cdp.send("Runtime.enable");

const postBodies = [];
await cdp.send("Network.enable");
// 重新挂监听需要在 connect 之前注册 events；简单起见直接在 ws 上加。
cdp.ws.addEventListener("message", (ev) => {
  const m = JSON.parse(ev.data);
  if (m.method === "Network.requestWillBeSent" && m.params.request.method === "POST") {
    postBodies.push(m.params.request.postData || "");
  }
});

await cdp.send("Page.navigate", { url: baseURL + "/" });
await sleep(500);

const results = [];
const check = (name, pass, detail) => { results.push({ name, pass: !!pass, detail: detail ?? "" }); };

const JS = {
  setValue: (sel, val, isSelect) => {
    const proto = isSelect ? "HTMLSelectElement" : "HTMLInputElement";
    return `(function(){var el=document.querySelector(${JSON.stringify(sel)});var s=Object.getOwnPropertyDescriptor(${proto}.prototype,"value").set;s.call(el,${JSON.stringify(String(val))});el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));})()`;
  },
  fill: (data) => `(function(){
    function sv(el,v,sel){var proto=sel?"HTMLSelectElement":"HTMLInputElement";var s=Object.getOwnPropertyDescriptor(proto,"value").set;s.call(el,String(v));el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));}
    sv(document.getElementById("name"),${JSON.stringify(data.name)});
    sv(document.getElementById("capacity"),${JSON.stringify(data.capacity)});
    sv(document.getElementById("timezone"),${JSON.stringify(data.timezone)});
    document.querySelectorAll("#hours-rows .hour-row").forEach(function(r){r.remove();});
    ${(data.hours || []).map((h, i) => `
      document.getElementById("add-hour").click();
      var r${i}=document.querySelectorAll("#hours-rows .hour-row")[${i}];
      sv(r${i}.querySelector(".hour-weekday"),${JSON.stringify(String(h.weekday))},true);
      ${h.start ? `sv(r${i}.querySelector(".hour-start"),${JSON.stringify(h.start)});` : ""}
      ${h.end ? `sv(r${i}.querySelector(".hour-end"),${JSON.stringify(h.end)});` : ""}
    `).join("")}
  })()`,
  submit: `document.getElementById("venue-form").dispatchEvent(new Event("submit",{bubbles:true,cancelable:true}))`,
  addRow: `document.getElementById("add-hour").click()`,
  state: `(function(){
    return {
      error: document.getElementById("form-error").style.display==="none"?null:document.getElementById("form-error").textContent,
      form: {
        name: document.getElementById("name").value,
        capacity: document.getElementById("capacity").value,
        timezone: document.getElementById("timezone").value,
        hours: Array.prototype.map.call(document.querySelectorAll("#hours-rows .hour-row"),function(r){
          return {weekday:r.querySelector(".hour-weekday").value,start:r.querySelector(".hour-start").value,end:r.querySelector(".hour-end").value};
        })
      },
      cards: Array.prototype.map.call(document.querySelectorAll(".venue-card"),function(c){return c.textContent.replace(/\\s+/g," ").trim();})
    };
  })()`,
};
const fill = (d) => cdp.eval(JS.fill(d));
const submit = () => cdp.eval(JS.submit);
const state = () => cdp.eval(JS.state);

// ===== 场景 A：提交“排练室/20/周一09:00-12:00”，等待期改名“会议室”并新增未完成行 =====
await fill({ name: "排练室", capacity: "20", timezone: "Asia/Shanghai", hours: [{ weekday: 1, start: "09:00", end: "12:00" }] });
submit();
await sleep(350);
await cdp.eval(JS.setValue("#name", "会议室"));
await cdp.eval(JS.addRow); // 注意：这是表达式字符串本身，eval 直接执行
await sleep(1400); // 等延迟响应 + 列表刷新

let s = await state();
check("A 提交报文是点击保存那一刻的排练室", postBodies.at(-1).includes('"name":"排练室"') && postBodies.at(-1).includes('"capacity":20'), postBodies.at(-1));
check("A 列表出现排练室卡片", s.cards.some((t) => t.includes("排练室") && t.includes("容量：20") && t.includes("周一 09:00 – 12:00")), JSON.stringify(s.cards));
check("A 列表不混入会议室", !s.cards.some((t) => t.includes("会议室")), JSON.stringify(s.cards));
check("A 表单名称保留为会议室", s.form.name === "会议室", s.form.name);
check("A 表单容量仍为 20", s.form.capacity === "20", s.form.capacity);
check("A 表单时区仍为 Asia/Shanghai", s.form.timezone === "Asia/Shanghai", s.form.timezone);
check("A 两行时段保留且顺序不变（第二行未完成）",
  s.form.hours.length === 2 && s.form.hours[0].weekday === "1" && s.form.hours[0].start === "09:00" && s.form.hours[0].end === "12:00"
  && s.form.hours[1].start === "" && s.form.hours[1].end === "", JSON.stringify(s.form.hours));
check("A 无错误提示", s.error === null, s.error);

// ===== 场景 B：保留下来的未完成行阻止再次保存，并指出第 2 行 =====
submit();
await sleep(400);
s = await state();
check("B 未完成时段阻止保存并指出第 2 行", s.error && s.error.includes("第 2 个开放时段未填写完整"), s.error);
check("B 阻止时表单完整保留", s.form.name === "会议室" && s.form.hours.length === 2, JSON.stringify(s.form));

// 补全第二行后成功保存会议室
await cdp.eval(`(function(){var r=document.querySelectorAll("#hours-rows .hour-row")[1];
  function sv(el,v){var d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set;d.call(el,v);el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));}
  sv(r.querySelector(".hour-start"),"14:00");sv(r.querySelector(".hour-end"),"16:00");})()`);
submit();
await sleep(1700);
s = await state();
check("B 补全后提交成功且报文为会议室两行",
  postBodies.at(-1).includes('"name":"会议室"') && postBodies.at(-1).includes('"weeklyHours":[{"weekday":1,"start":"09:00","end":"12:00"},{"weekday":1,"start":"14:00","end":"16:00"}]'),
  postBodies.at(-1));
check("B 列表同时有排练室与会议室两张卡片",
  s.cards.some((t) => t.includes("排练室")) && s.cards.some((t) => t.includes("会议室") && t.includes("14:00 – 16:00")),
  JSON.stringify(s.cards));
check("B 无改动后成功清空表单", s.form.name === "" && s.form.capacity === "" && s.form.hours.length === 0 && s.error === null, JSON.stringify(s.form));

// ===== 场景 C：等待期间改动后又改回提交时的原值，仍保留表单 =====
await fill({ name: "原样馆", capacity: "50", timezone: "UTC", hours: [] });
submit();
await sleep(300);
await cdp.eval(JS.setValue("#name", "临时名"));
await sleep(100);
await cdp.eval(JS.setValue("#name", "原样馆"));
await sleep(1300);
s = await state();
check("C 改回原值后成功仍不清空（名称保留）", s.form.name === "原样馆", s.form.name);
check("C 卡片来自已保存数据", s.cards.some((t) => t.includes("原样馆")), JSON.stringify(s.cards));

// ===== 场景 D：服务端在延迟后拒绝，等待期间有编辑：显示失败原因，保留当前内容 =====
await fill({ name: "被拒馆", capacity: "13", timezone: "UTC", hours: [] });
submit();
await sleep(300);
await cdp.eval(JS.setValue("#name", "被拒馆改稿"));
await sleep(1300);
s = await state();
check("D 显示服务端拒绝原因", s.error && s.error.includes("不吉利"), s.error);
check("D 表单保留等待期间的当前内容（不恢复旧值）", s.form.name === "被拒馆改稿" && s.form.capacity === "13", JSON.stringify(s.form));
check("D 列表无被拒馆卡片", !s.cards.some((t) => t.includes("被拒馆")), JSON.stringify(s.cards));

// ===== 场景 E：连接失败，等待期间有编辑：提示失败并保留当前内容 =====
// 用 fetch 前注入：直接构造一个指向会断连 URL 的请求不容易，改为让页面向
// /api/venues 提交 capacity 带 drop 标记——接口不接受额外字段但仍断连。
// 简单做法：提交后立刻改名，服务端 destroy 连接。
await fill({ name: "断连馆", capacity: "14", timezone: "UTC", hours: [] });
// 在请求体中塞入标记：通过劫持 fetch 一次。
await cdp.eval(`(function(){
  var orig = window.fetch;
  window.fetch = function(url, opts){
    if (opts && opts.method === "POST") { opts.body = opts.body.replace("}$", ',"drop":true}'); window.fetch = orig; }
    return orig.call(this, url, opts);
  };
})()`);
submit();
await sleep(300);
await cdp.eval(JS.setValue("#name", "断连馆改稿"));
await sleep(1500);
s = await state();
check("E 连接失败时提示无法连接服务", s.error && s.error.includes("无法连接服务"), s.error);
check("E 表单保留当前内容", s.form.name === "断连馆改稿" && s.form.capacity === "14", JSON.stringify(s.form));

// ===== 场景 F：等待期间只改容量为非法值，不阻止成功展示，且非法值保留 =====
await fill({ name: "合法馆", capacity: "90", timezone: "Asia/Tokyo", hours: [] });
submit();
await sleep(300);
await cdp.eval(JS.setValue("#capacity", "0"));
await sleep(1300);
s = await state();
check("F 合法提交成功入列表", s.cards.some((t) => t.includes("合法馆") && t.includes("容量：90")), JSON.stringify(s.cards));
check("F 等待期改成的非法容量 0 保留在表单", s.form.capacity === "0", s.form.capacity);
check("F 再次保存时非法容量被拦截", (async () => {}) && true);
submit();
await sleep(400);
s = await state();
check("F 再次保存提示容量必须为正整数", s.error && s.error.includes("正整数"), s.error);

let failed = 0;
for (const r of results) {
  console.log((r.pass ? "PASS " : "FAIL ") + r.name + (r.pass ? "" : "  -> " + r.detail));
  if (!r.pass) failed++;
}
console.log(`\n${results.length - failed}/${results.length} passed`);
try { process.kill(-chrome.pid, "SIGKILL"); } catch {}
server.close();
fs.rmSync(profile, { recursive: true, force: true });
process.exit(failed ? 1 : 0);

